package vaultor.linked;

import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Content-publication experiment, NOT accepted metadata admission. */
public final class ReplacementTests extends SafetyTests {
    static final String LOCAL="Local 😀\r\n";
    static class ReplacementFixture implements AutoCloseable {
        final Path dir=Files.createTempDirectory(Path.of("native/linked-markdown/.scratch"),"g3b-").toAbsolutePath(),root=Files.createDirectory(dir.resolve("root")),file=root.resolve("guide.md"),privateRoot=dir.resolve("private");
        final LinkedStore store;final String rootCap;final LinkedStore.Opened doc;
        ReplacementFixture(LinkedStore.Faults faults)throws Exception{Files.writeString(file,"Base\r\n");store=new LinkedStore(OWNER,privateRoot,VALIDATOR,CONSENT,List.of(dir.resolve("managed")),faults);rootCap=grant(store,root);doc=store.openRelative(OWNER,rootCap,"guide.md");}
        String prepare(String local)throws Exception{return candidate(store,doc,1,local);}
        public void close()throws Exception{store.close();}
        LinkedStore.Receipt publish(boolean observation)throws Exception{var receipt=store.replacementProbe(OWNER,doc.document(),doc.epoch(),prepare(LOCAL),UUID.randomUUID().toString(),observation);if(observation&&receipt.state().equals("RECOVERY_REQUIRED"))System.out.println("OBSERVATION_REFUSED "+store.recover(OWNER).stream().filter(r->r.operation().equals(receipt.operation())).map(r->r.record()==null?r.state():r.record().state()).toList());return receipt;}
    }
    static void observed(LinkedStore.Receipt r){require(r.state().equals("OBSERVED_NOT_QUALIFIED"));}
    public static void main(String[] args)throws Exception {
        System.setProperty("vaultor.linked.g3b.replacement-probe","true");
        if(args.length>0){crashChild(args);return;}
        check("replacement probe has no default write admission",()->{try(var f=new ReplacementFixture(null)){String ticket=f.prepare(LOCAL);System.clearProperty("vaultor.linked.g3b.replacement-probe");try{rejects("G3B_PROBE_ONLY",()->f.store.replacementProbe(OWNER,f.doc.document(),f.doc.epoch(),ticket,UUID.randomUUID().toString(),true));require(Files.readString(f.file).equals("Base\r\n"));}finally{System.setProperty("vaultor.linked.g3b.replacement-probe","true");}}});
        check("strict metadata admission refuses unreadable or unqualified SACL before detach",()->{try(var f=new ReplacementFixture(null)){var receipt=f.publish(false);require(receipt.state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base\r\n"));require(f.store.recover(OWNER).stream().anyMatch(r->r.record()!=null&&r.record().state().contains("SACL_")));}});
        check("fresh inode publication retains captured B, L and V without qualified Save receipt",()->{try(var f=new ReplacementFixture(null)){var receipt=f.publish(true);observed(receipt);require(Files.readString(f.file).equals(LOCAL));require(!receipt.revision().identity().equals(f.doc.base().revision().identity()));require(f.store.recover(OWNER).stream().anyMatch(r->r.captured()&&Arrays.equals(r.record().base(),LinkedStore.utf8("Base\r\n"))&&r.record().visual().contains("recover me")));}});
        for(String phase:List.of("replacement-compared","replacement-stage-chunk","replacement-staged","replacement-before-capture"))check("old outside alias stays B when introduced at "+phase,()->{final Path[] file={null},alias={null};final boolean[] made={false};try(var f=new ReplacementFixture((at,op)->{if(at.equals(phase)&&!made[0]){require(external("hardlink",alias[0],file[0].toString())==0);made[0]=true;}})){file[0]=f.file;alias[0]=f.dir.resolve("outside-alias.md");observed(f.publish(true));require(made[0]);require(Files.readString(alias[0]).equals("Base\r\n"));require(Files.readString(f.file).equals(LOCAL));}});
        check("existing hardlinked source is refused with both names intact",()->{try(var f=new ReplacementFixture(null)){Path alias=f.dir.resolve("existing-alias.md");Files.createLink(alias,f.file);require(f.publish(true).state().equals("RECOVERY_REQUIRED"));require(Files.readString(alias).equals("Base\r\n"));require(Files.readString(f.file).equals("Base\r\n"));}});
        check("old alias retains inspected security, creation and modified times after capture",()->{final Path[] file={null},alias={null};final String[] security={null};final java.nio.file.attribute.BasicFileAttributes[] attributes={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-before-capture")){require(external("hardlink",alias[0],file[0].toString())==0);security[0]=MetadataAudit.security(alias[0]);attributes[0]=Files.readAttributes(alias[0],java.nio.file.attribute.BasicFileAttributes.class);}})){file[0]=f.file;alias[0]=f.dir.resolve("alias.md");observed(f.publish(true));require(Files.readString(alias[0]).equals("Base\r\n"));require(MetadataAudit.security(alias[0]).equals(security[0]));var after=Files.readAttributes(alias[0],java.nio.file.attribute.BasicFileAttributes.class);require(after.creationTime().equals(attributes[0].creationTime()));require(after.lastModifiedTime().equals(attributes[0].lastModifiedTime()));}});
        check("published alias retains L on next attempted publication; hardlinked file refused",()->{try(var f=new ReplacementFixture(null)){observed(f.publish(true));Path alias=f.dir.resolve("new-alias.md");require(external("hardlink",alias,f.file.toString())==0);var doc=f.store.openRelative(OWNER,f.rootCap,f.file.getFileName().toString());throw new AssertionError("hardlinked reopen unexpectedly admitted: "+doc.document());}catch(IOException expected){require(expected.getMessage().contains("SINGLE_LINK"));}});
        for(String phase:List.of("replacement-captured","replacement-before-publish"))check("captured old inode alias remains B at "+phase,()->{final Path[] alias={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals(phase))require(external("hardlink",alias[0],op.resolve("captured.md").toString())==0);})){alias[0]=f.dir.resolve("outside.md");observed(f.publish(true));require(Files.readString(alias[0]).equals("Base\r\n"));require(Files.readString(f.file).equals(LOCAL));}});
        check("new alias at publication retains L and forces uncertain receipt",()->{final Path[] file={null},alias={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-published"))require(external("hardlink",alias[0],file[0].toString())==0);})){file[0]=f.file;alias[0]=f.dir.resolve("after.md");require(f.publish(true).state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals(LOCAL));require(Files.readString(alias[0]).equals(LOCAL));}});
        for(String phase:List.of("replacement-prepared","replacement-before-lease"))for(String mode:List.of("write","replace"))check("prelease "+mode+" at "+phase+" preserved as conflict",()->{final Path[] file={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals(phase))require(external(mode,file[0],"External")==0);})){file[0]=f.file;require(f.publish(true).state().equals("CONFLICT"));require(Files.readString(f.file).equals("External"));require(f.store.recover(OWNER).stream().anyMatch(r->Files.exists(f.privateRoot.resolve(r.operation()).resolve("external.md"))));}});
        for(String mode:List.of("write","replace","delete"))check("independent "+mode+" blocked between comparison and capture",()->{final Path[] file={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-staged"))require(external(mode,file[0],"External")==2);})){file[0]=f.file;observed(f.publish(true));require(Files.readString(f.file).equals(LOCAL));}});
        check("interloper hardlink in capture gap is never overwritten",()->{final Path[] file={null},outside={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-before-publish"))require(external("hardlink",file[0],outside[0].toString())==0);})){file[0]=f.file;outside[0]=f.dir.resolve("independent.md");Files.writeString(outside[0],"Independent");var receipt=f.publish(true);require(receipt.state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Independent"));require(Files.readString(outside[0]).equals("Independent"));require(Files.readString(f.privateRoot.resolve(receipt.operation()).resolve("captured.md")).equals("Base\r\n"));require(Files.readString(f.privateRoot.resolve(receipt.operation()).resolve("stage.md")).equals(LOCAL));}});
        for(String phase:List.of("replacement-released","replacement-finalized"))for(String mode:List.of("write","replace","delete"))check("postpublication "+mode+" at "+phase+" never reports success",()->{final Path[] file={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals(phase))require(external(mode,file[0],"External newer")==0);})){file[0]=f.file;var receipt=f.publish(true);require(receipt.state().equals("RECOVERY_REQUIRED"));if(mode.equals("delete"))require(!Files.exists(f.file));else{require(Files.readString(f.file).equals("External newer"));require(Files.readString(f.privateRoot.resolve(receipt.operation()).resolve("external.md")).equals("External newer"));}require(Files.readString(f.privateRoot.resolve(receipt.operation()).resolve("captured.md")).equals("Base\r\n"));}});
        check("metadata-only readonly mutation refuses source capture",()->{final Path[] file={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-compared"))require(external("readonly",file[0],"")==0);})){file[0]=f.file;require(f.publish(true).state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base\r\n"));}});
        check("ADS introduced by independent process is retained and publication refused",()->{final Path[] file={null};final int[] code={-1};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-compared"))code[0]=external("ads",file[0],"Stream evidence");})){file[0]=f.file;var receipt=f.publish(true);require(code[0]==0);require(receipt.state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base\r\n"));require(NamedStreamProbe.access(f.file+":fixture",null).equals("Stream evidence"));}});
        check("mapped original refuses before capture and map data is not replaced",()->{try(var f=new ReplacementFixture(null)){var child=process("vaultor.linked.MappedWriter",Base64.getEncoder().encodeToString(LinkedStore.utf8(f.file.toString())));require(new BufferedReader(new InputStreamReader(child.getInputStream())).readLine().equals("MAPPED"));try{require(f.publish(true).state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base\r\n"));}finally{child.getOutputStream().write(1);child.getOutputStream().flush();require(child.waitFor()==0);}require(Files.readString(f.file).startsWith("Ease"));}});
        check("independent DACL protection change is detected without source content mutation",()->{final Path[] file={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-compared"))require(external("protect-dacl",file[0],"")==0);})){file[0]=f.file;require(f.publish(true).state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base\r\n"));}});
        check("real compressed source refuses admission without changing its bytes",()->{try(var f=new ReplacementFixture(null)){PublicationCandidates.compress(f.file);require(f.publish(true).state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base\r\n"));require((WindowsFiles.attributes(f.file).attributes()&0x800)!=0);}});
        check("real NTFS EA source refuses admission and retains attributes",()->{try(var f=new ReplacementFixture(null)){MetadataAudit.setEa(f.file);String ea=MetadataAudit.ea(f.file);require(f.publish(true).state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base\r\n"));require(MetadataAudit.ea(f.file).equals(ea));}});
        check("independent source lease refuses publication without breaking its lock",()->{try(var f=new ReplacementFixture(null)){var child=process("vaultor.linked.Adversary","hold",Base64.getEncoder().encodeToString(LinkedStore.utf8(f.file.toString())));require(new BufferedReader(new InputStreamReader(child.getInputStream())).readLine().equals("READY"));try{require(f.publish(true).state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Base\r\n"));}finally{child.getOutputStream().write(1);child.getOutputStream().flush();require(child.waitFor()==0);}}});
        check("real empty-root junction mutation is detected without touching outside target",()->{final Path[] root={null},outside={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-captured")){int move=external("move",root[0],root[0].resolveSibling("moved").toString());System.out.println("EMPTY_PARENT_MOVE="+move);require(move==2);int junction=external("junction",root[0],outside[0].toString());System.out.println("EMPTY_PARENT_JUNCTION="+junction);require(junction==0);}})){root[0]=f.root;outside[0]=Files.createDirectory(f.dir.resolve("outside"));Files.writeString(outside[0].resolve("guide.md"),"Outside");var receipt=f.publish(true);require(receipt.state().equals("RECOVERY_REQUIRED"));require(Files.readString(outside[0].resolve("guide.md")).equals("Outside"));require(Files.readString(f.privateRoot.resolve(receipt.operation()).resolve("captured.md")).equals("Base\r\n"));}});
        check("revocation at last publication boundary leaves captured evidence without publishing",()->{final ReplacementFixture[] reference={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-before-publish"))reference[0].store.revoke(OWNER,reference[0].rootCap);})){reference[0]=f;var receipt=f.publish(true);require(receipt.state().equals("RECOVERY_REQUIRED"));require(!Files.exists(f.file));require(Files.readString(f.privateRoot.resolve(receipt.operation()).resolve("captured.md")).equals("Base\r\n"));}});
        check("ambiguous gap cannot be retried with the consumed candidate",()->{final Path[] file={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-captured"))require(external("create",file[0],"Independent")==0);})){file[0]=f.file;String ticket=f.prepare(LOCAL);var receipt=f.store.replacementProbe(OWNER,f.doc.document(),f.doc.epoch(),ticket,UUID.randomUUID().toString(),true);require(receipt.state().equals("RECOVERY_REQUIRED"));rejects("UNVALIDATED",()->f.store.replacementProbe(OWNER,f.doc.document(),f.doc.epoch(),ticket,UUID.randomUUID().toString(),true));require(Files.readString(f.file).equals("Independent"));}});
        check("reviewed missing-path restore refuses a fresh unrelated occupant",()->{try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-captured"))throw new IOException("INTERRUPTED_AFTER_CAPTURE");})){var receipt=f.publish(true);require(!Files.exists(f.file));var review=f.store.reviewRecovery(OWNER,receipt.operation(),f.rootCap);require(review.state().equals("PATH_MISSING"));require(external("create",f.file,"Independent")==0);rejects("RenameRelativeExclusive",()->f.store.restoreMissingBase(OWNER,review.ticket()));require(Files.readString(f.file).equals("Independent"));require(Files.readString(f.privateRoot.resolve(receipt.operation()).resolve("captured.md")).equals("Base\r\n"));}});
        check("corrupt recovery record cannot authorize restoration or source writes",()->{try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-captured"))throw new IOException("INTERRUPTED_AFTER_CAPTURE");})){var receipt=f.publish(true);Files.write(f.privateRoot.resolve(receipt.operation()).resolve("09.rec"),new byte[]{7});rejects("CORRUPT",()->f.store.reviewRecovery(OWNER,receipt.operation(),f.rootCap));require(!Files.exists(f.file));require(Files.readString(f.privateRoot.resolve(receipt.operation()).resolve("captured.md")).equals("Base\r\n"));}});
        check("same-byte pathname reuse after publication is still uncertain",()->{final Path[] file={null};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-finalized"))require(external("replace",file[0],LOCAL)==0);})){file[0]=f.file;require(f.publish(true).state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals(LOCAL));}});
        check("twenty reopened content publications retain every displaced B without automatic cleanup",()->{try(var f=new ReplacementFixture(null)){for(int i=0;i<20;i++){String before=Files.readString(f.file);var opened=f.store.openRelative(OWNER,f.rootCap,"guide.md");String next="Revision "+i+" 😀\r\n";var receipt=f.store.replacementProbe(OWNER,opened.document(),opened.epoch(),candidate(f.store,opened,1,next),UUID.randomUUID().toString(),true);observed(receipt);require(Files.readString(f.file).equals(next));require(Files.readString(f.privateRoot.resolve(receipt.operation()).resolve("captured.md")).equals(before));f.store.closeDocument(OWNER,opened.document());}require(f.store.recover(OWNER).stream().filter(Journal.Recovery::captured).count()==20);}});
        check("native POSIX replacing process cannot cause an uncontested lost external revision",()->{final Path[] file={null},alias={null};final int[] code={-1};try(var f=new ReplacementFixture((at,op)->{if(at.equals("replacement-compared")){require(external("hardlink",alias[0],file[0].toString())==0);code[0]=external("posix-replace",file[0],"Native external");System.out.println("NATIVE_POSIX_ATTACK_EXIT="+code[0]);}})){file[0]=f.file;alias[0]=f.dir.resolve("alias.md");var receipt=f.publish(true);require(Files.readString(alias[0]).equals("Base\r\n"));if(code[0]==0){require(receipt.state().equals("RECOVERY_REQUIRED"));require(Files.readString(f.file).equals("Native external"));}else{require(code[0]==2);observed(receipt);require(Files.readString(f.file).equals(LOCAL));}}});
        for(String phase:List.of("replacement-prepared","replacement-stage-chunk","replacement-stage-before-flush","replacement-staged","replacement-metadata-ready","replacement-before-capture","replacement-captured-before-record","replacement-captured","replacement-before-publish","replacement-published-before-record","replacement-published","replacement-released","replacement-finalized"))check("independent process halt preserves B L V at "+phase,()->crash(phase));
        Files.createDirectories(Path.of("native/linked-markdown/evidence/g3b"));Files.writeString(Path.of("native/linked-markdown/evidence/g3b/replacement-tests.txt"),String.join("\n",results)+"\npassed="+passed+" failed="+failed+"\n");System.out.println("TOTAL "+passed+" passed; "+failed+" failed");if(failed>0)System.exit(1);
    }
    static void crashChild(String[] args)throws Exception {
        Path dir=Path.of(args[1]);try(var store=new LinkedStore(OWNER,dir.resolve("private"),VALIDATOR,CONSENT,List.of(dir.resolve("managed")),(at,op)->{if(at.equals(args[0]))Runtime.getRuntime().halt(76);})){String root=grant(store,dir.resolve("root"));var opened=store.openRelative(OWNER,root,"guide.md");store.replacementProbe(OWNER,opened.document(),opened.epoch(),candidate(store,opened,1,LOCAL),UUID.randomUUID().toString(),true);}
    }
    static void crash(String phase)throws Exception {
        Path dir=Files.createTempDirectory(Path.of("native/linked-markdown/.scratch"),"g3b-crash-").toAbsolutePath(),root=Files.createDirectory(dir.resolve("root")),file=root.resolve("guide.md");Files.writeString(file,"Base\r\n");var child=process("vaultor.linked.ReplacementTests",phase,dir.toString());child.getInputStream().readAllBytes();require(child.waitFor(10,java.util.concurrent.TimeUnit.SECONDS));require(child.exitValue()==76);
        try(var store=new LinkedStore(OWNER,dir.resolve("private"),VALIDATOR,CONSENT,List.of(dir.resolve("managed")),null)){
            var recovery=store.recover(OWNER).stream().filter(r->r.record()!=null&&r.record().state().startsWith("REPLACEMENT_")).findFirst().orElseThrow();var record=recovery.record();require(Arrays.equals(record.base(),LinkedStore.utf8("Base\r\n")));require(Arrays.equals(record.local(),LinkedStore.utf8(LOCAL)));require(record.visual().contains("recover me"));boolean gap=Set.of("replacement-captured-before-record","replacement-captured","replacement-before-publish").contains(phase);boolean published=Set.of("replacement-published-before-record","replacement-published","replacement-released","replacement-finalized").contains(phase);
            if(gap)require(!Files.exists(file));else require(Files.readString(file).equals(published?LOCAL:"Base\r\n"));
            if(gap||published)require(Files.readString(dir.resolve("private").resolve(recovery.operation()).resolve("captured.md")).equals("Base\r\n"));
            // Recovery inspection never republishes. Corruption cannot change it.
            Files.write(dir.resolve("private").resolve(recovery.operation()).resolve("09.rec"),new byte[]{1,2});require(store.recover(OWNER).stream().anyMatch(r->r.operation().equals(recovery.operation())&&r.damagedTail()));if(gap)require(!Files.exists(file));
        }
    }
}
